/*\n# AI Core Infrastructure — Provider Config, Prompt Library, Memory, Rate Limits\n\nCreates tables for AI provider config, prompt library, memory, rate limits, and usage aggregate RPCs.\n*/\n\n-- 1. AI Provider Config\nCREATE TABLE IF NOT EXISTS ai_provider_config (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  provider text UNIQUE NOT NULL,\n  display_name text NOT NULL,\n  enabled boolean NOT NULL DEFAULT false,\n  is_default boolean NOT NULL DEFAULT false,\n  fallback_priority int NOT NULL DEFAULT 0,\n  api_key_secret text,\n  default_model text,\n  available_models jsonb NOT NULL DEFAULT '[]'::jsonb,\n  max_tokens int NOT NULL DEFAULT 4096,\n  temperature numeric NOT NULL DEFAULT 0.7,\n  timeout_ms int NOT NULL DEFAULT 30000,\n  supports_streaming boolean NOT NULL DEFAULT true,\n  supports_vision boolean NOT NULL DEFAULT false,\n  supports_images boolean NOT NULL DEFAULT false,\n  health_status text NOT NULL DEFAULT 'unknown',\n  last_health_check timestamptz,\n  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n)
\nALTER TABLE ai_provider_config ENABLE ROW LEVEL SECURITY
\nDROP POLICY IF EXISTS "admin_select_provider_config" ON ai_provider_config
\nCREATE POLICY "admin_select_provider_config" ON ai_provider_config FOR SELECT TO authenticated USING (is_admin_user())
\nDROP POLICY IF EXISTS "admin_insert_provider_config" ON ai_provider_config
\nCREATE POLICY "admin_insert_provider_config" ON ai_provider_config FOR INSERT TO authenticated WITH CHECK (is_admin_user())
\nDROP POLICY IF EXISTS "admin_update_provider_config" ON ai_provider_config
\nCREATE POLICY "admin_update_provider_config" ON ai_provider_config FOR UPDATE TO authenticated USING (is_admin_user()) WITH CHECK (is_admin_user())
\nDROP POLICY IF EXISTS "admin_delete_provider_config" ON ai_provider_config
\nCREATE POLICY "admin_delete_provider_config" ON ai_provider_config FOR DELETE TO authenticated USING (is_admin_user())
\n\n-- 2. AI Prompts\nCREATE TABLE IF NOT EXISTS ai_prompts (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  key text UNIQUE NOT NULL,\n  title text NOT NULL,\n  description text NOT NULL DEFAULT '',\n  system_prompt text NOT NULL,\n  user_prompt_template text NOT NULL DEFAULT '',\n  version int NOT NULL DEFAULT 1,\n  is_active boolean NOT NULL DEFAULT true,\n  feature text NOT NULL DEFAULT 'chat',\n  tags text[] NOT NULL DEFAULT '{}',\n  variables jsonb NOT NULL DEFAULT '[]'::jsonb,\n  model_override text,\n  temperature_override numeric,\n  max_tokens_override int,\n  created_by uuid,\n  updated_by uuid,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n)
\nALTER TABLE ai_prompts ENABLE ROW LEVEL SECURITY
\nDROP POLICY IF EXISTS "authenticated_select_prompts" ON ai_prompts
\nCREATE POLICY "authenticated_select_prompts" ON ai_prompts FOR SELECT TO authenticated USING (is_active = true)
\nDROP POLICY IF EXISTS "admin_insert_prompts" ON ai_prompts
\nCREATE POLICY "admin_insert_prompts" ON ai_prompts FOR INSERT TO authenticated WITH CHECK (is_admin_user())
\nDROP POLICY IF EXISTS "admin_update_prompts" ON ai_prompts
\nCREATE POLICY "admin_update_prompts" ON ai_prompts FOR UPDATE TO authenticated USING (is_admin_user()) WITH CHECK (is_admin_user())
\nDROP POLICY IF EXISTS "admin_delete_prompts" ON ai_prompts
\nCREATE POLICY "admin_delete_prompts" ON ai_prompts FOR DELETE TO authenticated USING (is_admin_user())
\n\n-- 3. AI Prompt Versions\nCREATE TABLE IF NOT EXISTS ai_prompt_versions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  prompt_id uuid NOT NULL REFERENCES ai_prompts(id) ON DELETE CASCADE,\n  version int NOT NULL,\n  system_prompt text NOT NULL,\n  user_prompt_template text NOT NULL DEFAULT '',\n  changed_by uuid,\n  change_note text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now()\n)
\nCREATE INDEX IF NOT EXISTS idx_ai_prompt_versions_prompt_id ON ai_prompt_versions(prompt_id)
\nALTER TABLE ai_prompt_versions ENABLE ROW LEVEL SECURITY
\nDROP POLICY IF EXISTS "authenticated_select_prompt_versions" ON ai_prompt_versions
\nCREATE POLICY "authenticated_select_prompt_versions" ON ai_prompt_versions FOR SELECT TO authenticated USING (true)
\nDROP POLICY IF EXISTS "admin_insert_prompt_versions" ON ai_prompt_versions
\nCREATE POLICY "admin_insert_prompt_versions" ON ai_prompt_versions FOR INSERT TO authenticated WITH CHECK (is_admin_user())
\nDROP POLICY IF EXISTS "admin_delete_prompt_versions" ON ai_prompt_versions
\nCREATE POLICY "admin_delete_prompt_versions" ON ai_prompt_versions FOR DELETE TO authenticated USING (is_admin_user())
\n\n-- 4. AI Memory\nCREATE TABLE IF NOT EXISTS ai_memory (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL DEFAULT auth.uid(),\n  memory_type text NOT NULL DEFAULT 'context',\n  scope text NOT NULL DEFAULT 'user',\n  key text NOT NULL,\n  value jsonb NOT NULL DEFAULT '{}'::jsonb,\n  confidence numeric NOT NULL DEFAULT 1.0,\n  source text NOT NULL DEFAULT 'inferred',\n  access_count int NOT NULL DEFAULT 0,\n  last_accessed_at timestamptz,\n  expires_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n)
\nCREATE UNIQUE INDEX IF NOT EXISTS idx_ai_memory_user_scope_key ON ai_memory(user_id, scope, key)
\nCREATE INDEX IF NOT EXISTS idx_ai_memory_user_id ON ai_memory(user_id)
\nCREATE INDEX IF NOT EXISTS idx_ai_memory_user_scope ON ai_memory(user_id, scope)
\nCREATE INDEX IF NOT EXISTS idx_ai_memory_user_type ON ai_memory(user_id, memory_type)
\nALTER TABLE ai_memory ENABLE ROW LEVEL SECURITY
\nDROP POLICY IF EXISTS "select_own_memory" ON ai_memory
\nCREATE POLICY "select_own_memory" ON ai_memory FOR SELECT TO authenticated USING (auth.uid() = user_id)
\nDROP POLICY IF EXISTS "insert_own_memory" ON ai_memory
\nCREATE POLICY "insert_own_memory" ON ai_memory FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id)
\nDROP POLICY IF EXISTS "update_own_memory" ON ai_memory
\nCREATE POLICY "update_own_memory" ON ai_memory FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id)
\nDROP POLICY IF EXISTS "delete_own_memory" ON ai_memory
\nCREATE POLICY "delete_own_memory" ON ai_memory FOR DELETE TO authenticated USING (auth.uid() = user_id)
\n\n-- 5. AI Rate Limits\nCREATE TABLE IF NOT EXISTS ai_rate_limits (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  tier text NOT NULL,\n  feature text NOT NULL DEFAULT 'all',\n  requests_per_minute int NOT NULL DEFAULT 20,\n  requests_per_hour int NOT NULL DEFAULT 200,\n  requests_per_day int NOT NULL DEFAULT 1000,\n  burst_limit int NOT NULL DEFAULT 5,\n  cooldown_seconds int NOT NULL DEFAULT 30,\n  is_active boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(tier, feature)\n)
\nALTER TABLE ai_rate_limits ENABLE ROW LEVEL SECURITY
\nDROP POLICY IF EXISTS "authenticated_select_rate_limits" ON ai_rate_limits
\nCREATE POLICY "authenticated_select_rate_limits" ON ai_rate_limits FOR SELECT TO authenticated USING (is_active = true)
\nDROP POLICY IF EXISTS "admin_insert_rate_limits" ON ai_rate_limits
\nCREATE POLICY "admin_insert_rate_limits" ON ai_rate_limits FOR INSERT TO authenticated WITH CHECK (is_admin_user())
\nDROP POLICY IF EXISTS "admin_update_rate_limits" ON ai_rate_limits
\nCREATE POLICY "admin_update_rate_limits" ON ai_rate_limits FOR UPDATE TO authenticated USING (is_admin_user()) WITH CHECK (is_admin_user())
\nDROP POLICY IF EXISTS "admin_delete_rate_limits" ON ai_rate_limits
\nCREATE POLICY "admin_delete_rate_limits" ON ai_rate_limits FOR DELETE TO authenticated USING (is_admin_user())
\n\n-- 6. Seed providers\nINSERT INTO ai_provider_config (provider, display_name, enabled, is_default, fallback_priority, api_key_secret, default_model, available_models, supports_streaming, supports_vision, supports_images)\nVALUES\n  ('groq', 'Groq', true, true, 0, 'GROQ_API_KEY', 'llama-3.3-70b-versatile', '[{"model":"llama-3.3-70b-versatile","label":"Llama 3.3 70B"},{"model":"llama-3.1-8b-instant","label":"Llama 3.1 8B (Fast)"}]'::jsonb, true, false, false),\n  ('gemini', 'Google Gemini', true, false, 1, 'GEMINI_API_KEY', 'gemini-2.0-flash-lite', '[{"model":"gemini-2.0-flash-lite","label":"Gemini 2.0 Flash Lite"},{"model":"gemini-2.0-flash","label":"Gemini 2.0 Flash"},{"model":"gemini-1.5-pro","label":"Gemini 1.5 Pro"}]'::jsonb, true, true, false),\n  ('openai', 'OpenAI', false, false, 2, 'OPENAI_API_KEY', 'gpt-4o-mini', '[{"model":"gpt-4o-mini","label":"GPT-4o mini"},{"model":"gpt-4o","label":"GPT-4o"},{"model":"gpt-4-turbo","label":"GPT-4 Turbo"}]'::jsonb, true, true, true),\n  ('anthropic', 'Anthropic Claude', false, false, 3, 'ANTHROPIC_API_KEY', 'claude-3-5-sonnet-20241022', '[{"model":"claude-3-5-sonnet-20241022","label":"Claude 3.5 Sonnet"},{"model":"claude-3-5-haiku-20241022","label":"Claude 3.5 Haiku"}]'::jsonb, true, true, false),\n  ('openrouter', 'OpenRouter', false, false, 4, 'OPENROUTER_API_KEY', 'auto', '[{"model":"auto","label":"Auto (best model)"},{"model":"openai/gpt-4o-mini","label":"GPT-4o mini"},{"model":"anthropic/claude-3.5-sonnet","label":"Claude 3.5 Sonnet"}]'::jsonb, true, false, false),\n  ('ollama', 'Ollama (Local)', false, false, 99, null, 'llama3.2', '[{"model":"llama3.2","label":"Llama 3.2 (Local)"},{"model":"qwen2.5","label":"Qwen 2.5 (Local)"}]'::jsonb, true, false, false)\nON CONFLICT (provider) DO NOTHING
\n\n-- 7. Seed rate limits\nINSERT INTO ai_rate_limits (tier, feature, requests_per_minute, requests_per_hour, requests_per_day, burst_limit, cooldown_seconds)\nVALUES\n  ('anonymous', 'all', 5, 20, 50, 3, 60),\n  ('authenticated', 'all', 20, 200, 1000, 10, 30),\n  ('premium', 'all', 60, 1000, 5000, 20, 10),\n  ('admin', 'all', 120, 5000, 20000, 30, 5)\nON CONFLICT (tier, feature) DO NOTHING
\n\n-- 8. Seed prompts\nINSERT INTO ai_prompts (key, title, description, system_prompt, user_prompt_template, feature, tags, variables)\nVALUES\n  ('marketplace_assistant', 'Marketplace Assistant', 'General-purpose AI assistant', 'You are the DRIGHT AI Assistant, an intelligent helper for the DRIGHT digital marketplace platform. You help users with products, services, jobs, courses, referrals, promotions, wallet, orders, support, and analytics. Be concise, helpful, and actionable.', '{{user_message}}', 'marketplace-assistant', ARRAY['assistant','chat','general'], '[{"name":"user_message","description":"The user question or request"}]'::jsonb),\n  ('product_description_generator', 'Product Description Generator', 'Generates optimized product descriptions', 'You are an expert e-commerce copywriter. Generate compelling, SEO-optimized product descriptions. Include relevant keywords naturally. Keep descriptions between 100-300 words.', 'Generate a product description for:\\n\\nProduct: {{product_name}}\\nCategory: {{category}}\\nKey features: {{features}}\\nTarget audience: {{target_audience}}', 'product-description', ARRAY['seller','product','seo','content'], '[{"name":"product_name","description":"Product name"},{"name":"category","description":"Product category"},{"name":"features","description":"Key features"},{"name":"target_audience","description":"Target audience"}]'::jsonb),\n  ('seller_insights', 'Seller Insights', 'AI-powered insights for sellers', 'You are a marketplace business advisor. Analyze seller data and provide actionable insights to improve sales, visibility, and customer satisfaction.', 'Analyze this seller performance:\\n\\nStore: {{store_name}}\\nProducts: {{product_count}}\\nTotal sales: {{total_sales}}\\nAverage rating: {{avg_rating}}\\nTop categories: {{top_categories}}', 'seller-insights', ARRAY['seller','analytics','insights'], '[{"name":"store_name","description":"Store name"},{"name":"product_count","description":"Number of products"},{"name":"total_sales","description":"Total sales count"},{"name":"avg_rating","description":"Average rating"},{"name":"top_categories","description":"Top selling categories"}]'::jsonb),\n  ('buyer_recommendation', 'Buyer Recommendation', 'Personalized product recommendations', 'You are a personal shopping assistant. Based on user preferences, browsing history, and budget, recommend relevant products.', 'Recommend products for this buyer:\\n\\nBudget: {{budget}}\\nInterests: {{interests}}\\nPreviously viewed: {{viewed_products}}\\nPurchase history: {{purchase_history}}', 'recommend', ARRAY['buyer','recommendation','personalization'], '[{"name":"budget","description":"Maximum budget"},{"name":"interests","description":"User interests"},{"name":"viewed_products","description":"Recently viewed products"},{"name":"purchase_history","description":"Past purchases"}]'::jsonb),\n  ('product_qa', 'Product Q&A', 'Answers buyer questions about products', 'You are a product expert assistant. Answer questions about products accurately based on the provided product information. Be concise.', 'Product: {{product_name}}\\nDescription: {{product_description}}\\nCategory: {{category}}\\nPrice: {{price}}\\n\\nQuestion: {{question}}', 'product-qa', ARRAY['product','qa','buyer'], '[{"name":"product_name","description":"Product name"},{"name":"product_description","description":"Product description"},{"name":"category","description":"Product category"},{"name":"price","description":"Product price"},{"name":"question","description":"Buyer question"}]'::jsonb)\nON CONFLICT (key) DO NOTHING
\n\n-- 9. RPCs\nCREATE OR REPLACE FUNCTION get_ai_provider_config()\nRETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('provider',provider,'display_name',display_name,'enabled',enabled,'is_default',is_default,'fallback_priority',fallback_priority,'default_model',default_model,'available_models',available_models,'max_tokens',max_tokens,'temperature',temperature,'timeout_ms',timeout_ms,'supports_streaming',supports_streaming,'supports_vision',supports_vision,'supports_images',supports_images,'health_status',health_status,'last_health_check',last_health_check) ORDER BY is_default DESC, fallback_priority ASC), '[]'::jsonb)\n  FROM ai_provider_config WHERE enabled = true
\n$$
\n\nCREATE OR REPLACE FUNCTION get_ai_rate_limits_for_tier(p_tier text)\nRETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('tier',tier,'feature',feature,'requests_per_minute',requests_per_minute,'requests_per_hour',requests_per_hour,'requests_per_day',requests_per_day,'burst_limit',burst_limit,'cooldown_seconds',cooldown_seconds)), '[]'::jsonb)\n  FROM ai_rate_limits WHERE is_active = true AND tier = p_tier
\n$$
\n\nCREATE OR REPLACE FUNCTION get_ai_prompt_by_key(p_key text)\nRETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\n  SELECT jsonb_build_object('id',id,'key',key,'system_prompt',system_prompt,'user_prompt_template',user_prompt_template,'version',version,'feature',feature,'model_override',model_override,'temperature_override',temperature_override,'max_tokens_override',max_tokens_override,'variables',variables)\n  FROM ai_prompts WHERE key = p_key AND is_active = true LIMIT 1
\n$$
\n\nCREATE OR REPLACE FUNCTION get_ai_usage_daily(p_days int DEFAULT 7)\nRETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('date',d::date,'total_requests',COALESCE(req.c,0),'total_tokens',COALESCE(tok.c,0),'successful',COALESCE(suc.c,0),'failed',COALESCE(fail.c,0),'estimated_cost',COALESCE(cost.c,0),'avg_latency_ms',COALESCE(lat.c,0)) ORDER BY d), '[]'::jsonb)\n  FROM (SELECT generate_series((now()-(p_days||' days')::interval)::date, now()::date, '1 day'::interval)::date AS d) dates\n  LEFT JOIN (SELECT DATE(created_at) dt, COUNT(*) c FROM ai_usage WHERE created_at >= now()-(p_days||' days')::interval GROUP BY 1) req ON req.dt=d\n  LEFT JOIN (SELECT DATE(created_at) dt, SUM(tokens) c FROM ai_usage WHERE created_at >= now()-(p_days||' days')::interval GROUP BY 1) tok ON tok.dt=d\n  LEFT JOIN (SELECT DATE(created_at) dt, COUNT(*) FILTER (WHERE success=true) c FROM ai_usage WHERE created_at >= now()-(p_days||' days')::interval GROUP BY 1) suc ON suc.dt=d\n  LEFT JOIN (SELECT DATE(created_at) dt, COUNT(*) FILTER (WHERE success=false) c FROM ai_usage WHERE created_at >= now()-(p_days||' days')::interval GROUP BY 1) fail ON fail.dt=d\n  LEFT JOIN (SELECT DATE(created_at) dt, COALESCE(SUM(estimated_cost),0) c FROM ai_usage WHERE created_at >= now()-(p_days||' days')::interval GROUP BY 1) cost ON cost.dt=d\n  LEFT JOIN (SELECT DATE(created_at) dt, AVG(latency_ms) c FROM ai_usage WHERE created_at >= now()-(p_days||' days')::interval GROUP BY 1) lat ON lat.dt=d
\n$$
\n\nCREATE OR REPLACE FUNCTION get_ai_usage_monthly(p_months int DEFAULT 6)\nRETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('month',to_char(d,'YYYY-MM'),'total_requests',COALESCE(req.c,0),'total_tokens',COALESCE(tok.c,0),'estimated_cost',COALESCE(cost.c,0),'unique_users',COALESCE(usr.c,0)) ORDER BY d), '[]'::jsonb)\n  FROM (SELECT generate_series(date_trunc('month',now()-(p_months||' months')::interval), date_trunc('month',now()), '1 month'::interval) AS d) dates\n  LEFT JOIN (SELECT date_trunc('month',created_at) mt, COUNT(*) c FROM ai_usage WHERE created_at >= now()-(p_months||' months')::interval GROUP BY 1) req ON req.mt=d\n  LEFT JOIN (SELECT date_trunc('month',created_at) mt, SUM(tokens) c FROM ai_usage WHERE created_at >= now()-(p_months||' months')::interval GROUP BY 1) tok ON tok.mt=d\n  LEFT JOIN (SELECT date_trunc('month',created_at) mt, COALESCE(SUM(estimated_cost),0) c FROM ai_usage WHERE created_at >= now()-(p_months||' months')::interval GROUP BY 1) cost ON cost.mt=d\n  LEFT JOIN (SELECT date_trunc('month',created_at) mt, COUNT(DISTINCT user_id) c FROM ai_usage WHERE created_at >= now()-(p_months||' months')::interval GROUP BY 1) usr ON usr.mt=d
\n$$
\n\nCREATE OR REPLACE FUNCTION get_ai_user_usage_summary(p_user_id uuid DEFAULT auth.uid())\nRETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\n  SELECT jsonb_build_object('total_requests',COUNT(*),'total_tokens',COALESCE(SUM(tokens),0),'estimated_cost',COALESCE(SUM(estimated_cost),0),'avg_latency_ms',COALESCE(AVG(latency_ms),0),'success_rate',COALESCE(ROUND(AVG(CASE WHEN success THEN 1.0 ELSE 0.0 END)*100,2),0),'by_feature',COALESCE((SELECT jsonb_agg(jsonb_build_object('feature',feature,'requests',cnt)) FROM (SELECT feature,COUNT(*) cnt FROM ai_usage WHERE user_id=p_user_id GROUP BY feature ORDER BY cnt DESC) f),'[]'::jsonb),'by_provider',COALESCE((SELECT jsonb_agg(jsonb_build_object('provider',provider,'requests',cnt)) FROM (SELECT provider,COUNT(*) cnt FROM ai_usage WHERE user_id=p_user_id GROUP BY provider ORDER BY cnt DESC) p),'[]'::jsonb),'last_30_days',(SELECT COUNT(*) FROM ai_usage WHERE user_id=p_user_id AND created_at >= now()-'30 days'::interval))\n  FROM ai_usage WHERE user_id = p_user_id
\n$$
\n\nCREATE OR REPLACE FUNCTION get_ai_marketplace_usage_summary()\nRETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\n  SELECT jsonb_build_object('total_requests',COUNT(*),'total_tokens',COALESCE(SUM(tokens),0),'estimated_cost',COALESCE(SUM(estimated_cost),0),'avg_latency_ms',COALESCE(AVG(latency_ms),0),'success_rate',COALESCE(ROUND(AVG(CASE WHEN success THEN 1.0 ELSE 0.0 END)*100,2),0),'unique_users',COUNT(DISTINCT user_id),'by_feature',COALESCE((SELECT jsonb_agg(jsonb_build_object('feature',feature,'requests',cnt,'tokens',tok)) FROM (SELECT feature,COUNT(*) cnt,SUM(tokens) tok FROM ai_usage GROUP BY feature ORDER BY cnt DESC) f),'[]'::jsonb),'by_provider',COALESCE((SELECT jsonb_agg(jsonb_build_object('provider',provider,'requests',cnt,'tokens',tok)) FROM (SELECT provider,COUNT(*) cnt,SUM(tokens) tok FROM ai_usage GROUP BY provider ORDER BY cnt DESC) p),'[]'::jsonb),'top_users',COALESCE((SELECT jsonb_agg(jsonb_build_object('user_id',user_id,'requests',cnt,'tokens',tok)) FROM (SELECT user_id,COUNT(*) cnt,SUM(tokens) tok FROM ai_usage GROUP BY user_id ORDER BY cnt DESC LIMIT 20) u),'[]'::jsonb))\n  FROM ai_usage
\n$$
\n\nCREATE OR REPLACE FUNCTION save_ai_memory(\n  p_key text,\n  p_value jsonb DEFAULT '{}'::jsonb,\n  p_user_id uuid DEFAULT auth.uid(),\n  p_memory_type text DEFAULT 'context',\n  p_scope text DEFAULT 'user',\n  p_confidence numeric DEFAULT 1.0,\n  p_source text DEFAULT 'inferred'\n)\nRETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE v_id uuid
\nBEGIN\n  INSERT INTO ai_memory (user_id, memory_type, scope, key, value, confidence, source)\n  VALUES (p_user_id, p_memory_type, p_scope, p_key, p_value, p_confidence, p_source)\n  ON CONFLICT (user_id, scope, key) DO UPDATE\n    SET value = p_value, confidence = GREATEST(ai_memory.confidence, p_confidence), source = p_source, updated_at = now()\n  RETURNING id INTO v_id
\n  RETURN v_id
\nEND
\n$$
\n\nCREATE OR REPLACE FUNCTION get_ai_memory(p_scope text DEFAULT 'user', p_memory_type text DEFAULT NULL)\nRETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'memory_type',memory_type,'scope',scope,'key',key,'value',value,'confidence',confidence,'source',source,'access_count',access_count,'last_accessed_at',last_accessed_at,'updated_at',updated_at) ORDER BY updated_at DESC), '[]'::jsonb)\n  FROM ai_memory WHERE user_id = auth.uid() AND scope = p_scope AND (p_memory_type IS NULL OR memory_type = p_memory_type)
\n$$
\n\nCREATE OR REPLACE FUNCTION search_ai_memory(p_query text)\nRETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\n  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'memory_type',memory_type,'scope',scope,'key',key,'value',value,'confidence',confidence) ORDER BY updated_at DESC), '[]'::jsonb)\n  FROM ai_memory WHERE user_id = auth.uid() AND (key ILIKE '%'||p_query||'%' OR value::text ILIKE '%'||p_query||'%')\n  LIMIT 50
\n$$
\n\nCREATE OR REPLACE FUNCTION auto_version_prompt()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nBEGIN\n  IF (TG_OP = 'UPDATE' AND (OLD.system_prompt IS DISTINCT FROM NEW.system_prompt OR OLD.user_prompt_template IS DISTINCT FROM NEW.user_prompt_template)) THEN\n    INSERT INTO ai_prompt_versions (prompt_id, version, system_prompt, user_prompt_template, changed_by, change_note)\n    VALUES (OLD.id, OLD.version, OLD.system_prompt, OLD.user_prompt_template, OLD.updated_by, 'Auto-versioned before update')
\n    NEW.version := OLD.version + 1
\n  END IF
\n  NEW.updated_at := now()
\n  RETURN NEW
\nEND
\n$$
\n\nDROP TRIGGER IF EXISTS trigger_auto_version_prompt ON ai_prompts
\nCREATE TRIGGER trigger_auto_version_prompt BEFORE UPDATE ON ai_prompts FOR EACH ROW EXECUTE FUNCTION auto_version_prompt()
\n\nGRANT EXECUTE ON FUNCTION get_ai_provider_config() TO authenticated
\nGRANT EXECUTE ON FUNCTION get_ai_rate_limits_for_tier(text) TO authenticated
\nGRANT EXECUTE ON FUNCTION get_ai_prompt_by_key(text) TO authenticated
\nGRANT EXECUTE ON FUNCTION get_ai_usage_daily(int) TO authenticated
\nGRANT EXECUTE ON FUNCTION get_ai_usage_monthly(int) TO authenticated
\nGRANT EXECUTE ON FUNCTION get_ai_user_usage_summary(uuid) TO authenticated
\nGRANT EXECUTE ON FUNCTION get_ai_marketplace_usage_summary() TO authenticated
\nGRANT EXECUTE ON FUNCTION save_ai_memory(text, jsonb, uuid, text, text, numeric, text) TO authenticated
\nGRANT EXECUTE ON FUNCTION get_ai_memory(text, text) TO authenticated
\nGRANT EXECUTE ON FUNCTION search_ai_memory(text) TO authenticated
